#include <stdio.h>
#include <stdlib.h>
static int compare_ints(const void *left, const void *right) { int a = *(const int *)left; int b = *(const int *)right; return (a > b) - (a < b); }
int main(void) { int values[] = {9, 2, 5, 1}; qsort(values, 4, sizeof values[0], compare_ints); for (int i = 0; i < 4; ++i) printf("%d%c", values[i], i == 3 ? '\n' : ' '); return 0; }

#include <stdio.h>
#include <string.h>
int main(void) { char text[32] = "wasm test"; printf("%zu %d\n", strlen(text), strcmp(text, "wasm test") == 0); return 0; }

#include <stdio.h>
static void swap(int *a, int *b) { int temporary = *a; *a = *b; *b = temporary; }
int main(void) { int left = 7, right = 12; swap(&left, &right); printf("%d %d\n", left, right); return 0; }

#include <stdio.h>
struct Student { const char *name; int age; };
int main(void) { struct Student student = {"Ada", 21}; printf("%s:%d\n", student.name, student.age); return 0; }

#include <stdio.h>
#include <stdlib.h>
int main(void) { int *values = calloc(3, sizeof *values); if (!values) return 2; values[0] = 1; values[1] = 2; values[2] = 3; printf("%d\n", values[0] + values[1] + values[2]); free(values); return 0; }

#include <stdio.h>
static unsigned long factorial(unsigned int value) { return value < 2 ? 1 : value * factorial(value - 1); }
int main(void) { printf("%lu\n", factorial(6)); return 0; }

#include <math.h>
#include <stdio.h>
int main(void) { double result = sqrt(81.0) + ceil(2.3) + floor(1.8); printf("%.0f\n", result); return 0; }

#include <stdio.h>
enum Grade { FAIL = 0, PASS = 1 };
static enum Grade grade(int score) { return score >= 50 ? PASS : FAIL; }
int main(void) { printf("%d %d\n", grade(49), grade(75)); return 0; }
